class AdditionalServicesDialogController{constructor($mdDialog,DispatchData,toastrService,jobId,clientId,speedId,quantity){this._$mdDialog=$mdDialog;this._dispatchData=DispatchData;this._toastrService=toastrService;this._jobId=jobId;this._clientId=clientId;this._speedId=speedId;this._quantity=quantity;this.isLoading=false;this.totalCost=0;this.selected=[];this.additionalServices=[];this.totalServicesCount=0;this.refreshServices();this.addToSelectList=this.addToSelectList.bind(this);this.getTotal=this.getTotal.bind(this)}refreshServices(){this.isLoading=true;this._dispatchData.getServices(this._clientId,this._speedId,this._jobId).then(serviceResponse=>{this.additionalServices=serviceResponse.items;this.totalServicesCount=serviceResponse.totalCount;this.isLoading=false})}addToSelectList(){this.getTotal().then(total=>this.totalCost=total)}async getTotal(){let totalAmount=this.selected.reduce((total,item)=>{const itemCharge=item.perItem?item.rate*this._quantity:item.rate;return total+itemCharge},0);return this._dispatchData.ppdExclusiveAmount(this._clientId,totalAmount)}async bookServices(){try{const serviceIds=this.selected.map(service=>service.itemId);await this._dispatchData.addServicesToJob(this._jobId,serviceIds);this._toastrService.showSuccessToast(serviceIds.length+" total services have been added to job for $"+this.totalCost)}catch(error){this._toastrService.showErrorToast(error.message)}}cancel(){this._$mdDialog.cancel()}}